def cache_stats(exchange=None, marketType=None, resourceType=None, status=None, symbol=None, timeframe=None, limit=None, cursor=None, includeEntries=None, **_extra):
    import json, os, datetime, time, hashlib, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0346000" if __import__("os").path.isdir("./environment_mix/0346000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: 
                return json.load(f)
        except Exception: 
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: 
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): 
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0, tzinfo=datetime.timezone.utc)
    now = now_dt.isoformat().replace("+00:00", "Z")

    def _parse_iso(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _new_id(prefix):
        seed = f"{time.time_ns()}:{os.getpid()}:{prefix}".encode("utf-8")
        return f"{prefix}_{hashlib.sha256(seed).hexdigest()[:26]}"

    def _resolve_exchange(exchange_code, exchanges_rows):
        if exchange_code is None:
            return None, None, None
        if not isinstance(exchange_code, str) or not exchange_code.strip():
            return None, "INVALID_ARGUMENT", "exchange must be a non-empty string"
        ex = None
        for r in exchanges_rows:
            if isinstance(r, dict) and r.get("exchange_code") == exchange_code:
                ex = r
                break
        if not ex:
            return None, "EXCHANGE_NOT_FOUND", f"Exchange '{exchange_code}' not found"
        if ex.get("status") == "disabled":
            return ex, "EXCHANGE_DISABLED", f"Exchange '{exchange_code}' is disabled"
        return ex, None, None

    def _log_request(status_str, exchange_id=None, market_type=None, symbol_=None, timeframe_=None, limit_=None,
                     page=None, page_size=None, cache_action="bypass", cache_entry_id=None,
                     error_code=None, error_message=None, response_summary=None):
        reqs = _load("ccxt_requests.json")
        dur = int(max(0, (time.time() - t0) * 1000))
        row = {
            "id": _new_id("ccxt_req"),
            "tool_name": "cache-stats",
            "exchange_id": exchange_id,
            "credential_id": None,
            "market_type": market_type,
            "symbol": symbol_,
            "symbols": None,
            "timeframe": timeframe_,
            "limit": limit_,
            "page": page,
            "page_size": page_size,
            "side": None,
            "amount": None,
            "leverage": None,
            "margin_mode": None,
            "extra_params": None,
            "cache_action": cache_action,
            "cache_entry_id": cache_entry_id,
            "status": status_str,
            "http_status": None,
            "duration_ms": dur,
            "error_code": error_code,
            "error_message": error_message,
            "response_summary": response_summary,
            "created_at": now,
            "updated_at": now,
        }
        reqs.append(row)
        _save("ccxt_requests.json", reqs)
        return row

    mt_enum = {"spot", "future", "swap", "option", "margin"}
    rt_enum = {"ticker", "tickers", "orderbook", "ohlcv", "trades", "markets", "exchange_info", "leverage_tiers", "funding_rates", "market_types"}
    st_enum = {"valid", "stale", "invalidated"}

    if exchange is not None and not isinstance(exchange, str):
        _log_request("error", error_code="INVALID_ARGUMENT", error_message="exchange must be a string", cache_action="bypass")
        return _err("VALIDATION_ERROR", "exchange must be a string", error_code="INVALID_ARGUMENT")
    if marketType is not None and marketType not in mt_enum:
        _log_request("error", market_type=marketType, error_code="INVALID_ARGUMENT", error_message="Invalid marketType", cache_action="bypass")
        return _err("VALIDATION_ERROR", "Invalid marketType", error_code="INVALID_ARGUMENT")
    if resourceType is not None and resourceType not in rt_enum:
        _log_request("error", market_type=marketType, error_code="INVALID_ARGUMENT", error_message="Invalid resourceType", cache_action="bypass")
        return _err("VALIDATION_ERROR", "Invalid resourceType", error_code="INVALID_ARGUMENT")
    if status is not None and status not in st_enum:
        _log_request("error", market_type=marketType, error_code="INVALID_ARGUMENT", error_message="Invalid status", cache_action="bypass")
        return _err("VALIDATION_ERROR", "Invalid status", error_code="INVALID_ARGUMENT")
    if symbol is not None and (not isinstance(symbol, str) or not symbol.strip()):
        _log_request("error", market_type=marketType, symbol_=symbol if isinstance(symbol, str) else None, error_code="INVALID_ARGUMENT", error_message="symbol must be a non-empty string", cache_action="bypass")
        return _err("VALIDATION_ERROR", "symbol must be a non-empty string", error_code="INVALID_ARGUMENT")
    if timeframe is not None and (not isinstance(timeframe, str) or not timeframe.strip()):
        _log_request("error", market_type=marketType, timeframe_=timeframe if isinstance(timeframe, str) else None, error_code="INVALID_ARGUMENT", error_message="timeframe must be a non-empty string", cache_action="bypass")
        return _err("VALIDATION_ERROR", "timeframe must be a non-empty string", error_code="INVALID_ARGUMENT")
    if includeEntries is not None and not isinstance(includeEntries, bool):
        _log_request("error", market_type=marketType, error_code="INVALID_ARGUMENT", error_message="includeEntries must be a boolean", cache_action="bypass")
        return _err("VALIDATION_ERROR", "includeEntries must be a boolean", error_code="INVALID_ARGUMENT")
    if limit is not None:
        if not isinstance(limit, int):
            _log_request("error", market_type=marketType, limit_=None, error_code="INVALID_ARGUMENT", error_message="limit must be an integer", cache_action="bypass")
            return _err("VALIDATION_ERROR", "limit must be an integer", error_code="INVALID_ARGUMENT")
        if limit < 1 or limit > 1000:
            _log_request("error", market_type=marketType, limit_=limit, error_code="INVALID_ARGUMENT", error_message="limit must be between 1 and 1000", cache_action="bypass")
            return _err("VALIDATION_ERROR", "limit must be between 1 and 1000", error_code="INVALID_ARGUMENT")
    if cursor is not None and not isinstance(cursor, str):
        _log_request("error", market_type=marketType, error_code="INVALID_ARGUMENT", error_message="cursor must be a string", cache_action="bypass")
        return _err("VALIDATION_ERROR", "cursor must be a string", error_code="INVALID_ARGUMENT")

    # Cursor decoding: base64url(json {"v":1,"o":int}) OR legacy "v1:<offset>"
    offset = 0
    if cursor:
        if cursor.startswith("v1:"):
            try:
                offset = int(cursor.split(":", 1)[1])
            except Exception:
                _log_request("error", market_type=marketType, error_code="INVALID_ARGUMENT", error_message="Malformed cursor", cache_action="bypass")
                return _err("VALIDATION_ERROR", "Malformed cursor", error_code="INVALID_ARGUMENT")
        else:
            try:
                pad = "=" * (-len(cursor) % 4)
                raw = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
                obj = json.loads(raw)
                if not isinstance(obj, dict) or obj.get("v") != 1 or not isinstance(obj.get("o"), int) or obj["o"] < 0:
                    raise ValueError("bad cursor")
                offset = obj["o"]
            except Exception:
                _log_request("error", market_type=marketType, error_code="INVALID_ARGUMENT", error_message="Malformed cursor", cache_action="bypass")
                return _err("VALIDATION_ERROR", "Malformed cursor", error_code="INVALID_ARGUMENT")
    if offset < 0:
        offset = 0

    exchanges_rows = _load("exchanges.json")
    ex_row, ex_err, ex_err_msg = _resolve_exchange(exchange, exchanges_rows)
    if ex_err:
        _log_request("error", exchange_id=(ex_row or {}).get("id") if isinstance(ex_row, dict) else None, market_type=marketType, symbol_=symbol, timeframe_=timeframe, limit_=limit, error_code=ex_err, error_message=ex_err_msg, cache_action="bypass")
        return _err("NOT_FOUND" if ex_err == "EXCHANGE_NOT_FOUND" else "CONFLICT", ex_err_msg, error_code=ex_err)

    cache_rows = _load("ccxt_cache_entries.json")
    # Filter rows
    filtered = []
    ex_id = ex_row.get("id") if isinstance(ex_row, dict) else None
    for r in cache_rows:
        if not isinstance(r, dict):
            continue
        if ex_id is not None and r.get("exchange_id") != ex_id:
            continue
        if marketType is not None and r.get("market_type") != marketType:
            continue
        if resourceType is not None and r.get("resource_type") != resourceType:
            continue
        if status is not None and r.get("status") != status:
            continue
        if symbol is not None and r.get("symbol") != symbol:
            continue
        if timeframe is not None and r.get("timeframe") != timeframe:
            continue
        filtered.append(r)

    # Optional aggregation limiting (for "large caches"): cap number of entries used for stats
    agg_limit = limit if isinstance(limit, int) else len(filtered)
    agg_rows = filtered[:max(0, agg_limit)]

    counts_by_status = {k: 0 for k in sorted(st_enum)}
    counts_by_resource = {k: 0 for k in sorted(rt_enum)}
    total_payload_bytes = 0
    total_hit_count = 0
    oldest_dt = None
    newest_dt = None
    unexpired_valid = 0

    for r in agg_rows:
        st = r.get("status")
        rt = r.get("resource_type")
        if st in counts_by_status:
            counts_by_status[st] += 1
        if rt in counts_by_resource:
            counts_by_resource[rt] += 1
        pb = r.get("payload_bytes")
        if isinstance(pb, int) and pb >= 0:
            total_payload_bytes += pb
        hc = r.get("hit_count")
        if isinstance(hc, int) and hc >= 0:
            total_hit_count += hc
        cdt = _parse_iso(r.get("created_at"))
        if cdt:
            oldest_dt = cdt if oldest_dt is None or cdt < oldest_dt else oldest_dt
            newest_dt = cdt if newest_dt is None or cdt > newest_dt else newest_dt

        if r.get("status") == "valid":
            exp = _parse_iso(r.get("expires_at"))
            if exp and exp > now_dt:
                unexpired_valid += 1

    stats = {
        "matched_total": len(filtered),
        "aggregated_count": len(agg_rows),
        "counts_by_status": counts_by_status,
        "counts_by_resource_type": counts_by_resource,
        "total_payload_bytes": total_payload_bytes,
        "total_hit_count": total_hit_count,
        "oldest_created_at": oldest_dt.isoformat().replace("+00:00", "Z") if oldest_dt else None,
        "newest_created_at": newest_dt.isoformat().replace("+00:00", "Z") if newest_dt else None,
        "valid_unexpired_count": unexpired_valid,
    }

    entries_out = None
    next_cursor = None
    has_more = False
    if includeEntries:
        # Entries pagination uses limit (default 100)
        page_limit = limit if isinstance(limit, int) else 100
        page_limit = max(1, min(1000, page_limit))
        page_rows = filtered[offset:offset + page_limit]
        entries_out = []
        for r in page_rows:
            entries_out.append({
                "id": r.get("id"),
                "exchange_id": r.get("exchange_id"),
                "market_type": r.get("market_type"),
                "resource_type": r.get("resource_type"),
                "symbol": r.get("symbol"),
                "symbols": r.get("symbols"),
                "timeframe": r.get("timeframe"),
                "limit": r.get("limit"),
                "page": r.get("page"),
                "page_size": r.get("page_size"),
                "cache_key": r.get("cache_key"),
                "status": r.get("status"),
                "ttl_seconds": r.get("ttl_seconds"),
                "expires_at": r.get("expires_at"),
                "hit_count": r.get("hit_count"),
                "last_hit_at": r.get("last_hit_at"),
                "payload_bytes": r.get("payload_bytes"),
                "created_at": r.get("created_at"),
                "updated_at": r.get("updated_at"),
            })
        next_off = offset + len(page_rows)
        has_more = next_off < len(filtered)
        if has_more:
            payload = json.dumps({"v": 1, "o": next_off}, separators=(",", ":"), sort_keys=True).encode("utf-8")
            next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    _log_request(
        "success",
        exchange_id=ex_id,
        market_type=marketType,
        symbol_=symbol,
        timeframe_=timeframe,
        limit_=limit if isinstance(limit, int) else None,
        cache_action="bypass",
        response_summary={"matched_total": len(filtered), "aggregated_count": len(agg_rows)}
    )

    return {
        "stats": stats,
        "entries": entries_out,
        "cursor": next_cursor,
        "has_more": has_more,
    }

def clear_cache(exchange=None, marketType=None, resourceType=None, symbol=None, timeframe=None, status=None, dryRun=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0346000" if __import__("os").path.isdir("./environment_mix/0346000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0, tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        seed = f"{time.time_ns()}:{os.getpid()}:{prefix}".encode("utf-8")
        return f"{prefix}_{hashlib.sha256(seed).hexdigest()[:26]}"

    def _log_request(status_str, exchange_id=None, market_type=None, symbol_=None, timeframe_=None,
                     cache_action="cleared", error_code=None, error_message=None, response_summary=None):
        reqs = _load("ccxt_requests.json")
        dur = int(max(0, (time.time() - t0) * 1000))
        row = {
            "id": _new_id("ccxt_req"),
            "tool_name": "clear-cache",
            "exchange_id": exchange_id,
            "credential_id": None,
            "market_type": market_type,
            "symbol": symbol_,
            "symbols": None,
            "timeframe": timeframe_,
            "limit": None,
            "page": None,
            "page_size": None,
            "side": None,
            "amount": None,
            "leverage": None,
            "margin_mode": None,
            "extra_params": None,
            "cache_action": cache_action,
            "cache_entry_id": None,
            "status": status_str,
            "http_status": None,
            "duration_ms": dur,
            "error_code": error_code,
            "error_message": error_message,
            "response_summary": response_summary,
            "created_at": now,
            "updated_at": now,
        }
        reqs.append(row)
        _save("ccxt_requests.json", reqs)
        return row

    mt_enum = {"spot", "future", "swap", "option", "margin"}
    rt_enum = {"ticker", "tickers", "orderbook", "ohlcv", "trades", "markets", "exchange_info", "leverage_tiers", "funding_rates", "market_types"}
    st_enum = {"valid", "stale", "invalidated"}

    if exchange is not None and not isinstance(exchange, str):
        _log_request("error", error_code="INVALID_ARGUMENT", error_message="exchange must be a string")
        return _err("VALIDATION_ERROR", "exchange must be a string", error_code="INVALID_ARGUMENT")
    if marketType is not None and marketType not in mt_enum:
        _log_request("error", market_type=marketType, error_code="INVALID_ARGUMENT", error_message="Invalid marketType")
        return _err("VALIDATION_ERROR", "Invalid marketType", error_code="INVALID_ARGUMENT")
    if resourceType is not None and resourceType not in rt_enum:
        _log_request("error", market_type=marketType, error_code="INVALID_ARGUMENT", error_message="Invalid resourceType")
        return _err("VALIDATION_ERROR", "Invalid resourceType", error_code="INVALID_ARGUMENT")
    if status is not None and status not in st_enum:
        _log_request("error", market_type=marketType, error_code="INVALID_ARGUMENT", error_message="Invalid status")
        return _err("VALIDATION_ERROR", "Invalid status", error_code="INVALID_ARGUMENT")
    if symbol is not None and (not isinstance(symbol, str) or not symbol.strip()):
        _log_request("error", market_type=marketType, symbol_=symbol if isinstance(symbol, str) else None, error_code="INVALID_ARGUMENT", error_message="symbol must be a non-empty string")
        return _err("VALIDATION_ERROR", "symbol must be a non-empty string", error_code="INVALID_ARGUMENT")
    if timeframe is not None and (not isinstance(timeframe, str) or not timeframe.strip()):
        _log_request("error", market_type=marketType, timeframe_=timeframe if isinstance(timeframe, str) else None, error_code="INVALID_ARGUMENT", error_message="timeframe must be a non-empty string")
        return _err("VALIDATION_ERROR", "timeframe must be a non-empty string", error_code="INVALID_ARGUMENT")
    if dryRun is not None and not isinstance(dryRun, bool):
        _log_request("error", market_type=marketType, error_code="INVALID_ARGUMENT", error_message="dryRun must be a boolean")
        return _err("VALIDATION_ERROR", "dryRun must be a boolean", error_code="INVALID_ARGUMENT")

    exchanges_rows = _load("exchanges.json")
    ex_row = None
    if exchange is not None:
        for r in exchanges_rows:
            if isinstance(r, dict) and r.get("exchange_code") == exchange:
                ex_row = r
                break
        if not ex_row:
            _log_request("error", error_code="EXCHANGE_NOT_FOUND", error_message=f"Exchange '{exchange}' not found")
            return _err("NOT_FOUND", f"Exchange '{exchange}' not found", error_code="EXCHANGE_NOT_FOUND")

    ex_id = ex_row.get("id") if isinstance(ex_row, dict) else None

    cache_rows = _load("ccxt_cache_entries.json")
    idxs = []
    for i, r in enumerate(cache_rows):
        if not isinstance(r, dict):
            continue
        if ex_id is not None and r.get("exchange_id") != ex_id:
            continue
        if marketType is not None and r.get("market_type") != marketType:
            continue
        if resourceType is not None and r.get("resource_type") != resourceType:
            continue
        if status is not None and r.get("status") != status:
            continue
        if symbol is not None and r.get("symbol") != symbol:
            continue
        if timeframe is not None and r.get("timeframe") != timeframe:
            continue
        idxs.append(i)

    if dryRun:
        _log_request("success", exchange_id=ex_id, market_type=marketType, symbol_=symbol, timeframe_=timeframe, cache_action="cleared", response_summary={"dry_run": True, "matched": len(idxs)})
        return {"dry_run": True, "matched": len(idxs), "cleared": 0}

    if not idxs:
        _log_request("error", exchange_id=ex_id, market_type=marketType, symbol_=symbol, timeframe_=timeframe, cache_action="cleared", error_code="NO_MATCH", error_message="No cache entries matched the provided filters")
        return _err("NOT_FOUND", "No cache entries matched the provided filters", error_code="NO_MATCH")

    # Invalidate (preferred to delete to preserve history)
    for i in idxs:
        r = cache_rows[i]
        if not isinstance(r, dict):
            continue
        r["status"] = "invalidated"
        r["updated_at"] = now
        # keep expires_at as-is; invalidation overrides validity regardless of expiry

    _save("ccxt_cache_entries.json", cache_rows)
    _log_request("success", exchange_id=ex_id, market_type=marketType, symbol_=symbol, timeframe_=timeframe, cache_action="cleared", response_summary={"invalidated": len(idxs)})

    return {"cleared": len(idxs), "invalidated": len(idxs)}

def set_log_level(level, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0346000" if __import__("os").path.isdir("./environment_mix/0346000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0, tzinfo=datetime.timezone.utc)
    now = now_dt.isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        seed = f"{time.time_ns()}:{os.getpid()}:{prefix}".encode("utf-8")
        return f"{prefix}_{hashlib.sha256(seed).hexdigest()[:26]}"

    def _parse_iso(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _pick_settings_row(settings_rows):
        # prefer scope=global; then any row
        if not isinstance(settings_rows, list):
            settings_rows = []
        for r in settings_rows:
            if isinstance(r, dict) and r.get("scope") == "global":
                return r
        for r in settings_rows:
            if isinstance(r, dict):
                return r
        return None

    def _log_request(status_str, error_code=None, error_message=None, response_summary=None, http_status=None):
        reqs = _load("ccxt_requests.json")
        dur = int(max(0, (time.time() - t0) * 1000))
        row = {
            "id": _new_id("ccxt_req"),
            "tool_name": "set-log-level",
            "exchange_id": None,
            "credential_id": None,
            "market_type": None,
            "symbol": None,
            "symbols": None,
            "timeframe": None,
            "limit": None,
            "page": None,
            "page_size": None,
            "side": None,
            "amount": None,
            "leverage": None,
            "margin_mode": None,
            "extra_params": {"level": level} if isinstance(level, str) else {"level": None},
            "cache_action": "bypass",
            "cache_entry_id": None,
            "status": status_str,
            "http_status": http_status,
            "duration_ms": dur,
            "error_code": error_code,
            "error_message": error_message,
            "response_summary": response_summary,
            "created_at": now,
            "updated_at": now,
        }
        reqs.append(row)
        _save("ccxt_requests.json", reqs)
        return row

    allowed = {"debug", "info", "warning", "error"}
    if not isinstance(level, str) or level not in allowed:
        _log_request("error", error_code="INVALID_ARGUMENT", error_message="level must be one of debug,info,warning,error", http_status=400)
        return _err("VALIDATION_ERROR", "level must be one of debug,info,warning,error", error_code="INVALID_ARGUMENT")

    settings = _load("server_settings.json")
    row = _pick_settings_row(settings)
    if row is None:
        # In a real deployment this would exist; here we cannot fabricate missing rows.
        _log_request("error", error_code="NOT_FOUND", error_message="server settings not found", http_status=404)
        return _err("NOT_FOUND", "server settings not found")

    # lifecycle: allow update from any state to any state per transitions; we won't change status here.
    row["log_level"] = level
    row["updated_by_tool"] = "set-log-level"
    # keep created_at; update updated_at
    if not row.get("created_at"):
        row["created_at"] = now
    row["updated_at"] = now
    _save("server_settings.json", settings)

    resp = {"logLevel": row.get("log_level")}
    _log_request("success", response_summary=resp, http_status=200)
    return resp

def get_ticker(exchange, symbol, marketType=None, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0346000" if __import__("os").path.isdir("./environment_mix/0346000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

