            out = {}
            for k in ("symbol", "timestamp", "datetime", "last", "bid", "ask", "high", "low", "baseVolume", "quoteVolume"):
                if k in payload:
                    out[k] = payload.get(k)
            return out or {"type": "object", "keys": len(payload)}
        return {"type": type(payload).__name__}

