                     error_code="EXCHANGE_DISABLED", error_message=f"Exchange '{exchange}' is disabled")
        return _err("NOT_FOUND", f"Exchange '{exchange}' is disabled")

    # Cache: do not reject symbol based on local markets; serve cached ticker if exists.
