            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0, tzinfo=datetime.timezone.utc)
    now = now_dt.isoformat().replace("+00:00", "Z")

    def _parse_iso(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _new_id(prefix):
        seed = f"{time.time_ns()}:{os.getpid()}:{prefix}".encode("utf-8")
        return f"{prefix}_{hashlib.sha256(seed).hexdigest()[:26]}"

    def _hash_cache_key(exchange_code, market_type, resource_type, symbol_=None, symbols_=None, timeframe_=None, limit_=None, page_=None, page_size_=None):
        canonical = {
            "exchange_code": exchange_code,
            "market_type": market_type,
            "resource_type": resource_type,
            "symbol": symbol_,
            "symbols": list(symbols_) if isinstance(symbols_, list) else symbols_,
            "timeframe": timeframe_,
            "limit": limit_,
            "page": page_,
            "page_size": page_size_,
        }
        blob = json.dumps(canonical, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        return hashlib.sha256(blob.encode("utf-8")).hexdigest()

    def _log_request(status_str, exchange_id=None, market_type=None, symbols_list=None, cache_action="bypass",
                     cache_entry_id=None, error_code=None, error_message=None, response_summary=None):
        reqs = _load("ccxt_requests.json")
        dur = int(max(0, (time.time() - t0) * 1000))
        row = {
            "id": _new_id("ccxt_req"),
            "tool_name": "batch-get-tickers",
            "exchange_id": exchange_id,
            "credential_id": None,
            "market_type": market_type,
            "symbol": None,
            "symbols": symbols_list,
            "timeframe": None,
            "limit": None,
            "page": None,
            "page_size": None,
            "side": None,
            "amount": None,
            "leverage": None,
            "margin_mode": None,
            "extra_params": None,
            "cache_action": cache_action,
            "cache_entry_id": cache_entry_id,
            "status": status_str,
            "http_status": None,
            "duration_ms": dur,
            "error_code": error_code,
            "error_message": error_message,
            "response_summary": response_summary,
            "created_at": now,
            "updated_at": now,
        }
        reqs.append(row)
        _save("ccxt_requests.json", reqs)
        return row

    mt_enum = {"spot", "future", "swap", "option", "margin"}

    if not isinstance(exchange, str) or not exchange.strip():
        _log_request("error", error_code="INVALID_ARGUMENT", error_message="exchange is required")
        return _err("VALIDATION_ERROR", "exchange is required", error_code="INVALID_ARGUMENT")
    if not isinstance(symbols, list) or len(symbols) == 0 or any((not isinstance(s, str) or not s.strip()) for s in symbols):
        _log_request("error", error_code="INVALID_ARGUMENT", error_message="symbols must be a non-empty array of strings", symbols_list=symbols if isinstance(symbols, list) else None)
        return _err("VALIDATION_ERROR", "symbols must be a non-empty array of strings", error_code="INVALID_ARGUMENT")

    settings_rows = _load("server_settings.json")
    settings = None
    for r in settings_rows:
        if isinstance(r, dict) and r.get("scope") == "global":
            settings = r
            break
    default_mt = (settings or {}).get("default_market_type") or "spot"
    eff_mt = default_mt if marketType is None else marketType
    if not isinstance(eff_mt, str) or eff_mt not in mt_enum:
        _log_request("error", market_type=eff_mt if isinstance(eff_mt, str) else None, symbols_list=symbols, error_code="INVALID_ARGUMENT", error_message="Invalid marketType")
        return _err("VALIDATION_ERROR", "Invalid marketType", error_code="INVALID_ARGUMENT")

    exchanges_rows = _load("exchanges.json")
    ex_row = None
    for r in exchanges_rows:
        if isinstance(r, dict) and r.get("exchange_code") == exchange:
            ex_row = r
            break
    if not ex_row:
        _log_request("error", market_type=eff_mt, symbols_list=symbols, error_code="EXCHANGE_NOT_FOUND", error_message=f"Exchange '{exchange}' not found")
        return _err("NOT_FOUND", f"Exchange '{exchange}' not found", error_code="EXCHANGE_NOT_FOUND")
    if ex_row.get("status") == "disabled":
        _log_request("error", exchange_id=ex_row.get("id"), market_type=eff_mt, symbols_list=symbols, error_code="EXCHANGE_DISABLED", error_message=f"Exchange '{exchange}' is disabled")
        return _err("CONFLICT", f"Exchange '{exchange}' is disabled", error_code="EXCHANGE_DISABLED")

    ex_id = ex_row.get("id")

    cache_rows = _load("ccxt_cache_entries.json")

    # First try a batch 'tickers' entry keyed by (exchange, marketType, symbols list)
    batch_key = _hash_cache_key(exchange, eff_mt, "tickers", symbols_=symbols)
    batch_row = None
    for r in cache_rows:
        if isinstance(r, dict) and r.get("cache_key") == batch_key:
            batch_row = r
            break

    out = {}
    served = 0
    cache_action = "miss"
    cache_entry_id = None

    if batch_row and batch_row.get("status") == "valid":
        exp = _parse_iso(batch_row.get("expires_at"))
        if exp and exp > now_dt:
            payload = batch_row.get("payload")
            if isinstance(payload, dict):
                # best effort: look up exact symbol keys; if absent, skip
                for s in symbols:
                    if s in payload:
                        out[s] = payload[s]
                        served += 1
            elif isinstance(payload, list):
                # list of tickers with "symbol" field
                for item in payload:
                    if isinstance(item, dict) and item.get("symbol") in symbols:
                        out[item.get("symbol")] = item
                        served += 1

            batch_row["hit_count"] = (batch_row.get("hit_count") if isinstance(batch_row.get("hit_count"), int) and batch_row.get("hit_count") >= 0 else 0) + 1
            batch_row["last_hit_at"] = now
            batch_row["updated_at"] = now
            _save("ccxt_cache_entries.json", cache_rows)

            cache_action = "hit"
            cache_entry_id = batch_row.get("id")

    # If batch entry didn't yield anything, try per-symbol 'ticker' cache entries
    if served == 0:
        for s in symbols:
            key = _hash_cache_key(exchange, eff_mt, "ticker", symbol_=s)
            row = None
            for r in cache_rows:
                if isinstance(r, dict) and r.get("cache_key") == key:
                    row = r
                    break
            if row and row.get("status") == "valid":
                exp = _parse_iso(row.get("expires_at"))
                if exp and exp > now_dt:
                    out[s] = row.get("payload")
                    served += 1
                    row["hit_count"] = (row.get("hit_count") if isinstance(row.get("hit_count"), int) and row.get("hit_count") >= 0 else 0) + 1
                    row["last_hit_at"] = now
                    row["updated_at"] = now
                    cache_action = "hit"
        if served > 0:
            _save("ccxt_cache_entries.json", cache_rows)

    # Must accept valid requests even if nothing cached: return empty set, not NOT_FOUND
    _log_request(
        "success",
        exchange_id=ex_id,
        market_type=eff_mt,
        symbols_list=symbols,
        cache_action=cache_action,
        cache_entry_id=cache_entry_id,
        response_summary={"requested": len(symbols), "returned": served}
    )
    return {"exchange": exchange, "marketType": eff_mt, "tickers": out, "requested": symbols, "returned": served}

