        }
        blob = json.dumps(canonical, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        return hashlib.sha256(blob.encode("utf-8")).hexdigest()

    def _resolve_settings_default_market_type():
        settings = _load("server_settings.json")
        if isinstance(settings, list):
            for r in settings:
                if isinstance(r, dict) and r.get("scope") == "global" and r.get("default_market_type") in mt_all:
                    return r.get("default_market_type")
            for r in settings:
                if isinstance(r, dict) and r.get("default_market_type") in mt_all:
                    return r.get("default_market_type")
        return "spot"

    def _resolve_exchange(exchange_code):
        exs = _load("exchanges.json")
        for r in exs if isinstance(exs, list) else []:
            if isinstance(r, dict) and r.get("exchange_code") == exchange_code:
                return r
        return None

    def _log_request(status_str, exchange_id=None, market_type=None, page_=None, page_size_=None, cache_action="bypass",
                     cache_entry_id=None, http_status=None, error_code=None, error_message=None, response_summary=None):
        reqs = _load("ccxt_requests.json")
        dur = int(max(0, (time.time() - t0) * 1000))
        row = {
            "id": _new_id("ccxt_req"),
            "tool_name": "get-markets",
            "exchange_id": exchange_id,
            "credential_id": None,
            "market_type": market_type,
            "symbol": None,
            "symbols": None,
            "timeframe": None,
            "limit": None,
            "page": page_,
            "page_size": page_size_,
            "side": None,
            "amount": None,
            "leverage": None,
            "margin_mode": None,
            "extra_params": None,
            "cache_action": cache_action,
            "cache_entry_id": cache_entry_id,
            "status": status_str,
            "http_status": http_status,
            "duration_ms": dur,
            "error_code": error_code,
            "error_message": error_message,
            "response_summary": response_summary,
            "created_at": now,
            "updated_at": now,
        }
