        _log_request("error", error_code="INVALID_ARGUMENT", error_message="page must be a positive integer", http_status=400, page_=page, page_size_=pageSize)
        return _err("VALIDATION_ERROR", "page must be a positive integer", error_code="INVALID_ARGUMENT")
    if not isinstance(pageSize, (int, float)) or not math.isfinite(float(pageSize)) or int(pageSize) != pageSize or int(pageSize) < 1 or int(pageSize) > 1000:
        _log_request("error", error_code="INVALID_ARGUMENT", error_message="pageSize must be an integer between 1 and 1000", http_status=400, page_=page, page_size_=pageSize)
        return _err("VALIDATION_ERROR", "pageSize must be an integer between 1 and 1000", error_code="INVALID_ARGUMENT")

