    ex = _resolve_exchange(exchange)
    if ex is None:
        _log_request("error", error_code="EXCHANGE_NOT_FOUND", error_message=f"Exchange '{exchange}' not found", http_status=404, market_type=marketType, page_=page, page_size_=pageSize)
        return _err("NOT_FOUND", f"Exchange '{exchange}' not found", error_code="EXCHANGE_NOT_FOUND")
