        _log_request("error", exchange_id=ex.get("id"), market_type=marketType, page_=page, page_size_=pageSize, error_code="EXCHANGE_DISABLED", error_message=f"Exchange '{exchange}' is disabled", http_status=403)
        return _err("CONFLICT", f"Exchange '{exchange}' is disabled", error_code="EXCHANGE_DISABLED")
