    cache = _load("ccxt_cache_entries.json")
    ck = _hash_cache_key(exchange, marketType, "markets", page_=page, page_size_=pageSize)
    entry = None
    for r in cache if isinstance(cache, list) else []:
        if isinstance(r, dict) and r.get("cache_key") == ck:
            entry = r
            break

    payload = None
    if entry and entry.get("status") == "valid":
        exp = _parse_iso(entry.get("expires_at"))
        if exp and exp > now_dt:
            entry["hit_count"] = int(entry.get("hit_count") or 0) + 1
            entry["last_hit_at"] = now
            entry["updated_at"] = now
            _save("ccxt_cache_entries.json", cache)
            payload = entry.get("payload")
            _log_request("success", exchange_id=ex.get("id"), market_type=marketType, page_=page, page_size_=pageSize,
                         cache_action="hit", cache_entry_id=entry.get("id"), http_status=200,
                         response_summary={"cached": True, "resource_type": "markets"})
    if payload is None:
        _log_request("success", exchange_id=ex.get("id"), market_type=marketType, page_=page, page_size_=pageSize,
                     cache_action="miss", cache_entry_id=entry.get("id") if entry else None, http_status=200,
                     response_summary={"cached": False, "resource_type": "markets"})
        payload = []

    # If cached markets payload is already paged, return it; otherwise slice if it's a list.
    items = payload
    if isinstance(payload, dict) and "items" in payload:
        items = payload.get("items") or []
        total = payload.get("total")
        if not isinstance(total, int):
            total = len(items)
    elif isinstance(payload, list):
        total = len(payload)
        start = (page - 1) * pageSize
        end = start + pageSize
        items = payload[start:end]
    else:
        total = 0
        items = []

    has_more = (page * pageSize) < total if isinstance(total, int) else False
    return {
        "items": items,
        "page": page,
