            "symbol": symbol_,
            "symbols": list(symbols_) if isinstance(symbols_, list) else symbols_,
            "timeframe": timeframe_,
            "limit": limit_,
            "page": page_,
            "page_size": page_size_,
        }
        blob = json.dumps(canonical, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        return hashlib.sha256(blob.encode("utf-8")).hexdigest()

    def _resolve_exchange(exchange_code):
        exs = _load("exchanges.json")
        if not isinstance(exs, list):
            return None
        for r in exs:
            if isinstance(r, dict) and r.get("exchange_code") == exchange_code:
                return r
        return None

    def _summarize(payload):
        if isinstance(payload, list):
            return {"type": "array", "length": len(payload)}
        if isinstance(payload, dict):
            return {"type": "object", "keys": len(payload)}
        return {"type": type(payload).__name__}

    def _log_request(*, status_str, exchange_id=None, market_type=None, symbol_=None, cache_action="bypass", cache_entry_id=None,
                     http_status=None, error_code=None, error_message=None, response_summary=None):
        reqs = _load("ccxt_requests.json")
        if not isinstance(reqs, list):
            reqs = []
        dur_ms = max(0, int((time.time() - t0) * 1000))
        row = {
            "id": _new_id("ccxt_req"),
            "tool_name": "get-leverage-tiers",
            "exchange_id": exchange_id,
            "credential_id": None,
            "market_type": market_type,
            "symbol": symbol_,
            "symbols": None,
            "timeframe": None,
            "limit": None,
            "page": None,
            "page_size": None,
            "side": None,
            "amount": None,
            "leverage": None,
            "margin_mode": None,
            "extra_params": None,
            "cache_action": cache_action,
            "cache_entry_id": cache_entry_id,
            "status": status_str,
            "http_status": http_status,
            "duration_ms": dur_ms,
            "error_code": error_code,
            "error_message": error_message,
            "response_summary": response_summary,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        reqs.append(row)
        _save("ccxt_requests.json", reqs)
        return row

    if not isinstance(exchange, str) or not exchange.strip():
        _log_request(status_str="error", cache_action="bypass", error_code="INVALID_ARGUMENT", error_message="exchange must be a non-empty string")
        return _err("VALIDATION_ERROR", "exchange must be a non-empty string")

    resolved_mt = marketType if marketType is not None else "future"
    if resolved_mt not in mt_allowed:
        _log_request(status_str="error", cache_action="bypass", error_code="INVALID_ARGUMENT", error_message="marketType must be 'future' or 'swap'")
        return _err("VALIDATION_ERROR", "marketType must be 'future' or 'swap'")

    if symbol is not None and (not isinstance(symbol, str) or not symbol.strip()):
        _log_request(status_str="error", cache_action="bypass", error_code="INVALID_ARGUMENT", error_message="symbol must be a non-empty string when provided")
        return _err("VALIDATION_ERROR", "symbol must be a non-empty string when provided")

    ex = _resolve_exchange(exchange)
    if not ex:
        _log_request(status_str="error", cache_action="bypass", error_code="EXCHANGE_NOT_FOUND", error_message=f"Exchange '{exchange}' not found")
        return _err("NOT_FOUND", f"Exchange '{exchange}' not found")
    if ex.get("status") == "disabled":
        _log_request(status_str="error", exchange_id=ex.get("id"), market_type=resolved_mt, symbol_=symbol, cache_action="bypass",
                     error_code="EXCHANGE_DISABLED", error_message=f"Exchange '{exchange}' is disabled")
        return _err("NOT_FOUND", f"Exchange '{exchange}' is disabled")

    cache = _load("ccxt_cache_entries.json")
    if not isinstance(cache, list):
        cache = []

    # If symbol provided, look for symbol-scoped cache; else exchange-wide leverage_tiers cache
    key = _hash_cache_key(exchange, resolved_mt, "leverage_tiers", symbol_=(symbol if symbol else None))
    chosen = None
    for e in cache:
        if isinstance(e, dict) and e.get("cache_key") == key:
            chosen = e
            break

    if chosen and chosen.get("status") == "valid":
        exp = _parse_iso(chosen.get("expires_at"))
        if exp and exp > now:
            chosen["hit_count"] = int(chosen.get("hit_count") or 0) + 1
            chosen["last_hit_at"] = now_iso
            chosen["updated_at"] = now_iso
            _save("ccxt_cache_entries.json", cache)
            payload = chosen.get("payload")
            # If symbol filter requested but payload is list, filter best-effort by common fields
            if symbol and isinstance(payload, list):
                filtered = []
                for it in payload:
                    if isinstance(it, dict) and (it.get("symbol") == symbol or it.get("info", {}).get("symbol") == symbol):
                        filtered.append(it)
                payload = filtered
            _log_request(status_str="success", exchange_id=ex.get("id"), market_type=resolved_mt, symbol_=symbol,
                         cache_action="hit", cache_entry_id=chosen.get("id"), response_summary=_summarize(payload))
            return {
                "exchange": exchange,
                "marketType": resolved_mt,
                "symbol": symbol,
                "cache": {"action": "hit", "cache_entry_id": chosen.get("id")},
                "data": payload,
            }

    _log_request(status_str="error", exchange_id=ex.get("id"), market_type=resolved_mt, symbol_=symbol,
                 cache_action="miss", cache_entry_id=(chosen.get("id") if isinstance(chosen, dict) else None),
                 error_code="NOT_CACHED", error_message="No cached leverage tiers available for requested parameters")
    return _err("NOT_FOUND", "No cached leverage tiers available for requested parameters")

