def get_market_types(exchange, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0346000" if __import__("os").path.isdir("./environment_mix/0346000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return prefix + "_" + hashlib.sha256(f"{time.time_ns()}:{os.getpid()}".encode()).hexdigest()[:16]

    def _log_request(tool_name, status, cache_action, exchange_id=None, credential_id=None,
                     market_type=None, symbol=None, symbols_list=None, timeframe=None, limit=None,
                     page=None, page_size=None, side=None, amount=None, leverage=None, margin_mode=None,
                     extra_params=None, cache_entry_id=None, http_status=None, error_code=None, error_message=None,
                     response_summary=None):
        reqs = _load("ccxt_requests.json")
        rid = _new_id("req")
        dur = int((time.time() - t0) * 1000)
        row = {
            "id": rid,
            "tool_name": tool_name,
            "exchange_id": exchange_id,
            "credential_id": credential_id,
            "market_type": market_type,
            "symbol": symbol,
            "symbols": symbols_list,
            "timeframe": timeframe,
            "limit": limit,
            "page": page,
            "page_size": page_size,
            "side": side,
            "amount": amount,
            "leverage": leverage,
            "margin_mode": margin_mode,
            "extra_params": extra_params,
            "cache_action": cache_action,
            "cache_entry_id": cache_entry_id,
            "status": status,
            "http_status": http_status,
            "duration_ms": max(0, dur),
            "error_code": error_code,
            "error_message": error_message,
            "response_summary": response_summary,
            "created_at": now,
            "updated_at": now,
        }
        reqs.append(row)
        _save("ccxt_requests.json", reqs)
        return row

    if not isinstance(exchange, str) or not exchange.strip():
        _log_request("get-market-types", "error", "bypass", error_code="INVALID_ARGUMENT", error_message="exchange is required")
        return _err("VALIDATION_ERROR", "exchange is required and must be a non-empty string")

    exchanges = _load("exchanges.json")
    ex_row = None
    for r in exchanges:
        if r.get("exchange_code") == exchange:
            ex_row = r
            break

    if ex_row is None:
        _log_request("get-market-types", "error", "bypass", error_code="EXCHANGE_NOT_FOUND", error_message="Exchange not found")
        return _err("NOT_FOUND", "Unknown exchange")

    if ex_row.get("status") == "disabled":
        _log_request("get-market-types", "error", "bypass", exchange_id=ex_row.get("id"),
                     error_code="EXCHANGE_DISABLED", error_message="Exchange is disabled")
        return _err("CONFLICT", "Exchange is disabled")

    # Prefer cached market_types resource if present/valid, else fall back to exchanges.supported_market_types.
    cache = _load("ccxt_cache_entries.json")

    def _hash_cache_key(exchange_code, market_type, resource_type, symbol, symbols_list, timeframe, limit, page, page_size):
        payload = {
            "exchange": exchange_code,
            "market_type": market_type,
            "resource_type": resource_type,
            "symbol": symbol,
            "symbols": symbols_list,
            "timeframe": timeframe,
            "limit": limit,
            "page": page,
            "page_size": page_size,
        }
        s = json.dumps(payload, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _is_unexpired_valid(crow):
        if not crow or crow.get("status") != "valid":
            return False
        exp = crow.get("expires_at")
        if not isinstance(exp, str) or not exp:
            return False
        try:
            if exp.endswith("Z"):
                dt = datetime.datetime.fromisoformat(exp[:-1])
            else:
                dt = datetime.datetime.fromisoformat(exp)
            return dt > datetime.datetime.utcnow().replace(microsecond=0)
        except Exception:
            return False

    # market_type dimension is required by schema for cache entries; we try default settings, then each supported.
    settings = _load("server_settings.json")
    default_mt = None
    for s in settings:
        if s.get("scope") == "global":
            default_mt = s.get("default_market_type")
            break

    candidate_mts = []
    if isinstance(default_mt, str) and default_mt:
        candidate_mts.append(default_mt)
    smt = ex_row.get("supported_market_types")
    if isinstance(smt, list):
        for mt in smt:
            if isinstance(mt, str) and mt not in candidate_mts:
                candidate_mts.append(mt)
    if not candidate_mts:
        candidate_mts = ["spot"]

    cache_row = None
    for mt in candidate_mts:
        ck = _hash_cache_key(exchange, mt, "market_types", None, None, None, None, None, None)
        for c in cache:
            if c.get("cache_key") == ck:
                cache_row = c
                break
        if cache_row:
            break

    if _is_unexpired_valid(cache_row):
        cache_row["hit_count"] = int(cache_row.get("hit_count") or 0) + 1
        cache_row["last_hit_at"] = now
        cache_row["updated_at"] = now
        _save("ccxt_cache_entries.json", cache)

        payload = cache_row.get("payload")
        if not isinstance(payload, list):
            payload = []
        _log_request("get-market-types", "success", "hit", exchange_id=ex_row.get("id"),
                     market_type=cache_row.get("market_type"), cache_entry_id=cache_row.get("id"),
                     response_summary={"items": len(payload)})
        return {"exchange": exchange, "marketTypes": payload, "cache": {"action": "hit", "cache_entry_id": cache_row.get("id")}}

    # No valid cache entry; return supported_market_types as capabilities view.
    types = ex_row.get("supported_market_types")
    if not isinstance(types, list):
        # Must be able to load capabilities; treat as upstream error per tool description.
        _log_request("get-market-types", "error", "miss", exchange_id=ex_row.get("id"),
                     error_code="UPSTREAM_ERROR", error_message="Exchange capabilities unavailable")
        return _err("NOT_FOUND", "Exchange capabilities unavailable", error_code="UPSTREAM_ERROR")

    # Log as success with bypass (not cache-backed), since we served from metadata.
    _log_request("get-market-types", "success", "bypass", exchange_id=ex_row.get("id"),
                 response_summary={"items": len(types)})
    return {"exchange": exchange, "marketTypes": types, "cache": {"action": "bypass"}}

