        return None

    def _upsert_credential(exchange_id, api_key_plain, secret_plain):
        creds = _load("exchange_credentials.json")
        if not isinstance(creds, list):
            creds = []
        fp = _fingerprint(api_key_plain)
        for c in creds:
            if isinstance(c, dict) and c.get("exchange_id") == exchange_id and c.get("api_key_fingerprint") == fp:
                # reactivate if revoked? business rules didn't allow; keep status.
                c["api_key_last4"] = (api_key_plain[-4:] if isinstance(api_key_plain, str) and len(api_key_plain) >= 4 else None)
                # store opaque/encrypted fields as provided (do not validate)
                c["api_key_encrypted"] = api_key_plain
                c["secret_encrypted"] = secret_plain
                c["updated_at"] = now
                return creds, c
        row = {
            "id": _new_id("ccxt_cred"),
            "exchange_id": exchange_id,
            "api_key_fingerprint": fp,
            "api_key_last4": (api_key_plain[-4:] if isinstance(api_key_plain, str) and len(api_key_plain) >= 4 else None),
            "api_key_encrypted": api_key_plain,
            "secret_encrypted": secret_plain,
            "status": "active",
            "last_used_at": now,
            "created_at": now,
            "updated_at": now,
        }
        creds.append(row)
        return creds, row

    def _log_request(status_str, exchange_id=None, credential_id=None, market_type=None,
                     error_code=None, error_message=None, response_summary=None, http_status=None):
        reqs = _load("ccxt_requests.json")
        dur = int(max(0, (time.time() - t0) * 1000))
        row = {
            "id": _new_id("ccxt_req"),
            "tool_name": "account-balance",
            "exchange_id": exchange_id,
            "credential_id": credential_id,
            "market_type": market_type,
            "symbol": None,
            "symbols": None,
            "timeframe": None,
            "limit": None,
            "page": None,
            "page_size": None,
            "side": None,
            "amount": None,
            "leverage": None,
            "margin_mode": None,
            "extra_params": None,
            "cache_action": "bypass",
            "cache_entry_id": None,
            "status": status_str,
            "http_status": http_status,
            "duration_ms": dur,
            "error_code": error_code,
            "error_message": error_message,
            "response_summary": response_summary,
            "created_at": now,
            "updated_at": now,
        }
        reqs.append(row)
        _save("ccxt_requests.json", reqs)
        return row

    if not isinstance(exchange, str) or not exchange.strip():
        _log_request("error", error_code="INVALID_ARGUMENT", error_message="exchange is required", http_status=400)
        return _err("VALIDATION_ERROR", "exchange is required", error_code="INVALID_ARGUMENT")
    if not isinstance(apiKey, str) or not apiKey.strip():
        _log_request("error", error_code="INVALID_ARGUMENT", error_message="apiKey is required", http_status=400)
        return _err("VALIDATION_ERROR", "apiKey is required", error_code="INVALID_ARGUMENT")
    if not isinstance(secret, str) or not secret.strip():
        _log_request("error", error_code="INVALID_ARGUMENT", error_message="secret is required", http_status=400)
        return _err("VALIDATION_ERROR", "secret is required", error_code="INVALID_ARGUMENT")

    if marketType is None:
        marketType = _resolve_settings_default_market_type()
    if not isinstance(marketType, str) or marketType not in mt_all:
        _log_request("error", error_code="INVALID_ARGUMENT", error_message="marketType is invalid", http_status=400, market_type=marketType)
        return _err("VALIDATION_ERROR", "marketType is invalid", error_code="INVALID_ARGUMENT")

    ex = _resolve_exchange(exchange)
    if ex is None:
        _log_request("error", error_code="EXCHANGE_NOT_FOUND", error_message=f"Exchange '{exchange}' not found", http_status=404, market_type=marketType)
        return _err("NOT_FOUND", f"Exchange '{exchange}' not found", error_code="EXCHANGE_NOT_FOUND")
    if ex.get("status") == "disabled":
        _log_request("error", exchange_id=ex.get("id"), error_code="EXCHANGE_DISABLED", error_message=f"Exchange '{exchange}' is disabled", http_status=403, market_type=marketType)
        return _err("CONFLICT", f"Exchange '{exchange}' is disabled", error_code="EXCHANGE_DISABLED")

    # upsert credential (do not log raw apiKey/secret anywhere except in credential store fields)
    creds, cred = _upsert_credential(ex.get("id"), apiKey, secret)
    cred["last_used_at"] = now
    _save("exchange_credentials.json", creds)

    # Offline mode: return a best-effort balance from cache if present; otherwise empty object (no error).
    cache = _load("ccxt_cache_entries.json")
    # search for any valid unexpired balance payload for this exchange+marketType, regardless of exact cache_key
    best = None
    for r in cache if isinstance(cache, list) else []:
        if not isinstance(r, dict): 
            continue
        if r.get("status") != "valid":
            continue
        if r.get("exchange_id") != ex.get("id"):
            continue
        if r.get("market_type") != marketType:
            continue
        if r.get("resource_type") in ("balance", "account_balance", "account-balance"):
            exp = _parse_iso(r.get("expires_at"))
            if exp and exp > now_dt:
                best = r
                break

    if best is not None:
        best["hit_count"] = int(best.get("hit_count") or 0) + 1
        best["last_hit_at"] = now
        best["updated_at"] = now
        _save("ccxt_cache_entries.json", cache)
        payload = best.get("payload") if isinstance(best.get("payload"), (dict, list)) else best.get("payload")
        _log_request("success", exchange_id=ex.get("id"), credential_id=cred.get("id"), market_type=marketType,
                     http_status=200, response_summary={"cached": True, "resource_type": best.get("resource_type")})
        return payload

    _log_request("success", exchange_id=ex.get("id"), credential_id=cred.get("id"), market_type=marketType,
                 http_status=200, response_summary={"cached": False})
    return {}

def place_market_order(exchange, symbol, side, amount, apiKey, secret, marketType=None, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0346000" if __import__("os").path.isdir("./environment_mix/0346000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0, tzinfo=datetime.timezone.utc)
    now = now_dt.isoformat().replace("+00:00", "Z")

    mt_all = {"spot", "future", "swap", "option", "margin"}
    side_all = {"buy", "sell"}

    def _new_id(prefix):
        seed = f"{time.time_ns()}:{os.getpid()}:{prefix}".encode("utf-8")
        return f"{prefix}_{hashlib.sha256(seed).hexdigest()[:26]}"

    def _fingerprint(k):
        if not isinstance(k, str):
            k = ""
        return hashlib.sha256(k.encode("utf-8")).hexdigest()

    def _resolve_settings_default_market_type():
        settings = _load("server_settings.json")
        if isinstance(settings, list):
            for r in settings:
                if isinstance(r, dict) and r.get("scope") == "global" and r.get("default_market_type") in mt_all:
                    return r.get("default_market_type")
            for r in settings:
                if isinstance(r, dict) and r.get("default_market_type") in mt_all:
                    return r.get("default_market_type")
        return "spot"

    def _resolve_exchange(exchange_code):
        exs = _load("exchanges.json")
        for r in exs if isinstance(exs, list) else []:
            if isinstance(r, dict) and r.get("exchange_code") == exchange_code:
                return r
        return None

    def _upsert_credential(exchange_id, api_key_plain, secret_plain):
        creds = _load("exchange_credentials.json")
        if not isinstance(creds, list):
            creds = []
        fp = _fingerprint(api_key_plain)
        for c in creds:
            if isinstance(c, dict) and c.get("exchange_id") == exchange_id and c.get("api_key_fingerprint") == fp:
                c["api_key_last4"] = (api_key_plain[-4:] if isinstance(api_key_plain, str) and len(api_key_plain) >= 4 else None)
                c["api_key_encrypted"] = api_key_plain
                c["secret_encrypted"] = secret_plain
                c["last_used_at"] = now
                c["updated_at"] = now
                return creds, c
        row = {
            "id": _new_id("ccxt_cred"),
            "exchange_id": exchange_id,
            "api_key_fingerprint": fp,
            "api_key_last4": (api_key_plain[-4:] if isinstance(api_key_plain, str) and len(api_key_plain) >= 4 else None),
            "api_key_encrypted": api_key_plain,
            "secret_encrypted": secret_plain,
            "status": "active",
            "last_used_at": now,
            "created_at": now,
            "updated_at": now,
        }
        creds.append(row)
        return creds, row

    def _log_request(status_str, exchange_id=None, credential_id=None, market_type=None, symbol_=None,
                     side_=None, amount_=None, error_code=None, error_message=None, response_summary=None, http_status=None):
        reqs = _load("ccxt_requests.json")
        dur = int(max(0, (time.time() - t0) * 1000))
        row = {
            "id": _new_id("ccxt_req"),
            "tool_name": "place-market-order",
            "exchange_id": exchange_id,
            "credential_id": credential_id,
            "market_type": market_type,
            "symbol": symbol_,
            "symbols": None,
            "timeframe": None,
            "limit": None,
            "page": None,
            "page_size": None,
            "side": side_,
            "amount": amount_,
            "leverage": None,
            "margin_mode": None,
            "extra_params": None,
            "cache_action": "bypass",
            "cache_entry_id": None,
            "status": status_str,
            "http_status": http_status,
            "duration_ms": dur,
            "error_code": error_code,
            "error_message": error_message,
            "response_summary": response_summary,
            "created_at": now,
            "updated_at": now,
        }
        reqs.append(row)
        _save("ccxt_requests.json", reqs)
        return row

    if not isinstance(exchange, str) or not exchange.strip():
        _log_request("error", error_code="INVALID_ARGUMENT", error_message="exchange is required", http_status=400)
        return _err("VALIDATION_ERROR", "exchange is required", error_code="INVALID_ARGUMENT")
    if not isinstance(symbol, str) or not symbol.strip():
        _log_request("error", error_code="INVALID_ARGUMENT", error_message="symbol is required", http_status=400)
        return _err("VALIDATION_ERROR", "symbol is required", error_code="INVALID_ARGUMENT")
    if not isinstance(side, str) or side not in side_all:
        _log_request("error", error_code="INVALID_ARGUMENT", error_message="side must be buy or sell", http_status=400, symbol_=symbol, side_=side, amount_=amount)
        return _err("VALIDATION_ERROR", "side must be buy or sell", error_code="INVALID_ARGUMENT")
    if not isinstance(amount, (int, float)) or amount <= 0:
        _log_request("error", error_code="INVALID_ARGUMENT", error_message="amount must be > 0", http_status=400, symbol_=symbol, side_=side, amount_=amount)
        return _err("VALIDATION_ERROR", "amount must be > 0", error_code="INVALID_ARGUMENT")
    if not isinstance(apiKey, str) or not apiKey.strip():
        _log_request("error", error_code="INVALID_ARGUMENT", error_message="apiKey is required", http_status=400, symbol_=symbol, side_=side, amount_=amount)
        return _err("VALIDATION_ERROR", "apiKey is required", error_code="INVALID_ARGUMENT")
    if not isinstance(secret, str) or not secret.strip():
        _log_request("error", error_code="INVALID_ARGUMENT", error_message="secret is required", http_status=400, symbol_=symbol, side_=side, amount_=amount)
        return _err("VALIDATION_ERROR", "secret is required", error_code="INVALID_ARGUMENT")

    if marketType is None:
        marketType = _resolve_settings_default_market_type()
    if not isinstance(marketType, str) or marketType not in mt_all:
        _log_request("error", error_code="INVALID_ARGUMENT", error_message="marketType is invalid", http_status=400, symbol_=symbol, side_=side, amount_=amount)
        return _err("VALIDATION_ERROR", "marketType is invalid", error_code="INVALID_ARGUMENT")

    ex = _resolve_exchange(exchange)
    if ex is None:
        _log_request("error", error_code="EXCHANGE_NOT_FOUND", error_message=f"Exchange '{exchange}' not found", http_status=404, market_type=marketType, symbol_=symbol, side_=side, amount_=amount)
        return _err("NOT_FOUND", f"Exchange '{exchange}' not found", error_code="EXCHANGE_NOT_FOUND")
    if ex.get("status") == "disabled":
        _log_request("error", exchange_id=ex.get("id"), error_code="EXCHANGE_DISABLED", error_message=f"Exchange '{exchange}' is disabled", http_status=403, market_type=marketType, symbol_=symbol, side_=side, amount_=amount)
        return _err("CONFLICT", f"Exchange '{exchange}' is disabled", error_code="EXCHANGE_DISABLED")

    # upsert credential
    creds, cred = _upsert_credential(ex.get("id"), apiKey, secret)
    _save("exchange_credentials.json", creds)

    # Offline: create a local "order" object and log success (effect: request row persisted; credential updated)
    order = {
        "id": _new_id("order"),
        "clientOrderId": None,
        "timestamp": int(now_dt.timestamp() * 1000),
        "datetime": now,
        "symbol": symbol,
        "type": "market",
        "side": side,
        "amount": float(amount),
        "price": None,
        "cost": None,
        "average": None,
        "filled": 0.0,
        "remaining": float(amount),
        "status": "open",
        "info": {"offline": True, "note": "Order simulated in local datastore"},
    }
    _log_request("success", exchange_id=ex.get("id"), credential_id=cred.get("id"),
                 market_type=marketType, symbol_=symbol, side_=side, amount_=float(amount),
                 http_status=200, response_summary={"offline": True, "order_id": order["id"]})
    return order

def set_margin_mode(exchange, symbol, marginMode, apiKey, secret, marketType=None, **_extra):
    import json, os, datetime, time, hashlib, base64, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0346000" if __import__("os").path.isdir("./environment_mix/0346000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    start = time.time()
    created_at = _now()

    # Load/ensure settings record exists
    settings = _load("server_settings.json")
    if not isinstance(settings, list):
        settings = []
    ss = None
    for r in settings:
        if isinstance(r, dict) and r.get("scope") == "global":
            ss = r
            break
    if ss is None:
        ss = {
            "id": "server_settings_global",
            "scope": "global",
            "status": "active",
            "log_level": "info",
            "default_market_type": "spot",
            "proxy_enabled": False,
            "proxy_url": "",
            "proxy_username": None,
            "proxy_password_encrypted": None,
            "proxy_last_test_exchange_id": None,
            "proxy_last_test_at": None,
            "proxy_last_test_status": None,
            "proxy_last_test_error": None,
            "updated_by_tool": None,
            "created_at": created_at,
            "updated_at": created_at,
        }
        settings.append(ss)
        _save("server_settings.json", settings)

    if marketType is None:
        marketType_eff = "future"
    else:
        marketType_eff = marketType

    reqs = _load("ccxt_requests.json")
    if not isinstance(reqs, list):
        reqs = []
    req_row = {
        "id": _new_id("req"),
        "tool_name": "set-margin-mode",
        "exchange_id": None,
        "credential_id": None,
        "market_type": marketType_eff,
        "symbol": symbol,
        "symbols": None,
        "timeframe": None,
        "limit": None,
        "page": None,
        "page_size": None,
        "side": None,
        "amount": None,
        "leverage": None,
        "margin_mode": marginMode,
        "extra_params": None,
        "cache_action": "bypass",
        "cache_entry_id": None,
        "status": "error",
        "http_status": 400,
        "duration_ms": 0,
        "error_code": None,
        "error_message": None,
        "response_summary": None,
        "created_at": created_at,
        "updated_at": created_at,
    }

    def _finalize_and_return(body, status="success", http_status=200, error_code=None, error_message=None, response_summary=None):
        ended = time.time()
        req_row["status"] = status
        req_row["http_status"] = http_status
        req_row["duration_ms"] = max(0, int(round((ended - start) * 1000)))
        req_row["error_code"] = error_code
        req_row["error_message"] = error_message
        req_row["response_summary"] = response_summary
        req_row["updated_at"] = _now()
        reqs.append(req_row)
        _save("ccxt_requests.json", reqs)
        return body

    # Validate inputs
    if not isinstance(exchange, str) or not exchange.strip():
        return _finalize_and_return(_err("VALIDATION_ERROR", "exchange must be a non-empty string"), status="error", http_status=400, error_code="INVALID_ARGUMENT", error_message="Invalid exchange")
    if not isinstance(symbol, str) or not symbol.strip():
        return _finalize_and_return(_err("VALIDATION_ERROR", "symbol must be a non-empty string"), status="error", http_status=400, error_code="INVALID_ARGUMENT", error_message="Invalid symbol")
    if marginMode not in ("cross", "isolated"):
        return _finalize_and_return(_err("VALIDATION_ERROR", "marginMode must be 'cross' or 'isolated'"), status="error", http_status=400, error_code="INVALID_ARGUMENT", error_message="Invalid marginMode")
    if marketType_eff not in ("future", "swap"):
        return _finalize_and_return(_err("VALIDATION_ERROR", "marketType must be 'future' or 'swap'"), status="error", http_status=400, error_code="INVALID_ARGUMENT", error_message="Invalid marketType")
    if not isinstance(apiKey, str) or not apiKey:
        return _finalize_and_return(_err("VALIDATION_ERROR", "apiKey is required"), status="error", http_status=400, error_code="INVALID_ARGUMENT", error_message="Missing apiKey")
    if not isinstance(secret, str) or not secret:
        return _finalize_and_return(_err("VALIDATION_ERROR", "secret is required"), status="error", http_status=400, error_code="INVALID_ARGUMENT", error_message="Missing secret")

    # Resolve exchange by exchange_code and status
    exchanges = _load("exchanges.json")
    if not isinstance(exchanges, list):
        exchanges = []
    ex = None
    for r in exchanges:
        if isinstance(r, dict) and r.get("exchange_code") == exchange:
            ex = r
            break
    if ex is None:
        return _finalize_and_return(_err("NOT_FOUND", "Exchange not found", exchange=exchange), status="error", http_status=404, error_code="EXCHANGE_NOT_FOUND", error_message="Exchange not found")
    req_row["exchange_id"] = ex.get("id")
    if ex.get("status") == "disabled":
        return _finalize_and_return(_err("CONFLICT", "Exchange is disabled", exchange=exchange), status="error", http_status=409, error_code="EXCHANGE_DISABLED", error_message="Exchange disabled")
    if not ex.get("has_private_api", False):
        return _finalize_and_return(_err("UNAUTHORIZED", "Exchange private API not available on this server"), status="error", http_status=401, error_code="AUTH_FAILED", error_message="Private API not available")

    smt = ex.get("supported_market_types")
    if not isinstance(smt, list) or marketType_eff not in smt:
        return _finalize_and_return(_err("VALIDATION_ERROR", "marketType not supported for this exchange", marketType=marketType_eff), status="error", http_status=400, error_code="INVALID_ARGUMENT", error_message="Unsupported marketType")

    # Upsert credential
    creds = _load("exchange_credentials.json")
    if not isinstance(creds, list):
        creds = []
    fp = hashlib.sha256(apiKey.encode("utf-8")).hexdigest()
    last4 = apiKey[-4:] if len(apiKey) >= 4 else apiKey
    cred = None
    for c in creds:
        if isinstance(c, dict) and c.get("exchange_id") == ex.get("id") and c.get("api_key_fingerprint") == fp:
            cred = c
            break
    now = _now()
    if cred is None:
        cred = {
            "id": _new_id("cred"),
            "exchange_id": ex.get("id"),
            "api_key_fingerprint": fp,
            "api_key_last4": last4,
            "api_key_encrypted": "opaque:" + base64.b64encode(apiKey.encode("utf-8")).decode("ascii"),
            "secret_encrypted": "opaque:" + base64.b64encode(secret.encode("utf-8")).decode("ascii"),
            "status": "active",
            "last_used_at": now,
            "created_at": now,
            "updated_at": now,
        }
        creds.append(cred)
        _save("exchange_credentials.json", creds)
    else:
        if cred.get("status") != "active":
            return _finalize_and_return(_err("UNAUTHORIZED", "Credential is revoked"), status="error", http_status=401, error_code="AUTH_FAILED", error_message="Credential revoked")
        cred["last_used_at"] = now
        cred["updated_at"] = now
        _save("exchange_credentials.json", creds)

    req_row["credential_id"] = cred.get("id")

    result = {
        "info": {
            "action": "setMarginMode",
            "exchange": exchange,
            "symbol": symbol,
            "marketType": marketType_eff,
        },
        "exchange": exchange,
        "symbol": symbol,
        "marginMode": marginMode,
        "status": "ok",
        "timestamp": int(datetime.datetime.utcnow().timestamp() * 1000),
        "datetime": _now(),
    }
    summary = {"status": "ok", "symbol": symbol, "marginMode": marginMode, "marketType": marketType_eff}
    return _finalize_and_return(result, status="success", http_status=200, response_summary=summary)

