            "updated_at": created_at,
        }
        settings.append(ss)
        _save("server_settings.json", settings)

    if marketType is None:
        marketType_eff = "future"
    else:
        marketType_eff = marketType

    reqs = _load("ccxt_requests.json")
    if not isinstance(reqs, list):
        reqs = []
    req_row = {
        "id": _new_id("req"),
        "tool_name": "place-futures-market-order",
        "exchange_id": None,
        "credential_id": None,
        "market_type": marketType_eff,
        "symbol": symbol,
        "symbols": None,
        "timeframe": None,
        "limit": None,
        "page": None,
        "page_size": None,
        "side": side,
        "amount": amount,
        "leverage": None,
        "margin_mode": None,
        "extra_params": params if isinstance(params, dict) else (None if params is None else {"_redacted": True}),
        "cache_action": "bypass",
        "cache_entry_id": None,
        "status": "error",
        "http_status": 400,
        "duration_ms": 0,
        "error_code": None,
        "error_message": None,
        "response_summary": None,
        "created_at": created_at,
        "updated_at": created_at,
    }

    def _finalize_and_return(body, status="success", http_status=200, error_code=None, error_message=None, response_summary=None):
        ended = time.time()
        req_row["status"] = status
        req_row["http_status"] = http_status
        req_row["duration_ms"] = max(0, int(round((ended - start) * 1000)))
        req_row["error_code"] = error_code
        req_row["error_message"] = error_message
        req_row["response_summary"] = response_summary
        req_row["updated_at"] = _now()
        reqs.append(req_row)
        _save("ccxt_requests.json", reqs)
        return body

    # Validate inputs
    if not isinstance(exchange, str) or not exchange.strip():
        return _finalize_and_return(_err("VALIDATION_ERROR", "exchange must be a non-empty string"), status="error", http_status=400, error_code="INVALID_ARGUMENT", error_message="Invalid exchange")
    if not isinstance(symbol, str) or not symbol.strip():
        return _finalize_and_return(_err("VALIDATION_ERROR", "symbol must be a non-empty string"), status="error", http_status=400, error_code="INVALID_ARGUMENT", error_message="Invalid symbol")
    if side not in ("buy", "sell"):
        return _finalize_and_return(_err("VALIDATION_ERROR", "side must be 'buy' or 'sell'"), status="error", http_status=400, error_code="INVALID_ARGUMENT", error_message="Invalid side")
    if not (isinstance(amount, int) or isinstance(amount, float)) or isinstance(amount, bool):
        return _finalize_and_return(_err("VALIDATION_ERROR", "amount must be a number"), status="error", http_status=400, error_code="INVALID_ARGUMENT", error_message="Invalid amount type")
    if amount <= 0:
        return _finalize_and_return(_err("VALIDATION_ERROR", "amount must be > 0"), status="error", http_status=400, error_code="INVALID_ARGUMENT", error_message="Amount must be > 0")
    if marketType_eff not in ("future", "swap"):
        return _finalize_and_return(_err("VALIDATION_ERROR", "marketType must be 'future' or 'swap'"), status="error", http_status=400, error_code="INVALID_ARGUMENT", error_message="Invalid marketType")
    if params is not None and not isinstance(params, dict):
        return _finalize_and_return(_err("VALIDATION_ERROR", "params must be an object"), status="error", http_status=400, error_code="INVALID_ARGUMENT", error_message="Invalid params")
    if not isinstance(apiKey, str) or not apiKey:
        return _finalize_and_return(_err("VALIDATION_ERROR", "apiKey is required"), status="error", http_status=400, error_code="INVALID_ARGUMENT", error_message="Missing apiKey")
    if not isinstance(secret, str) or not secret:
        return _finalize_and_return(_err("VALIDATION_ERROR", "secret is required"), status="error", http_status=400, error_code="INVALID_ARGUMENT", error_message="Missing secret")

    # Resolve exchange
    exchanges = _load("exchanges.json")
    if not isinstance(exchanges, list):
        exchanges = []
    ex = None
    for r in exchanges:
        if isinstance(r, dict) and r.get("exchange_code") == exchange:
            ex = r
            break
    if ex is None:
        return _finalize_and_return(_err("NOT_FOUND", "Exchange not found", exchange=exchange), status="error", http_status=404, error_code="EXCHANGE_NOT_FOUND", error_message="Exchange not found")
    req_row["exchange_id"] = ex.get("id")
    if ex.get("status") == "disabled":
        return _finalize_and_return(_err("CONFLICT", "Exchange is disabled", exchange=exchange), status="error", http_status=409, error_code="EXCHANGE_DISABLED", error_message="Exchange disabled")
    if not ex.get("has_private_api", False):
        return _finalize_and_return(_err("UNAUTHORIZED", "Exchange private API not available on this server"), status="error", http_status=401, error_code="AUTH_FAILED", error_message="Private API not available")

    smt = ex.get("supported_market_types")
    if not isinstance(smt, list) or marketType_eff not in smt:
        return _finalize_and_return(_err("VALIDATION_ERROR", "marketType not supported for this exchange", marketType=marketType_eff), status="error", http_status=400, error_code="INVALID_ARGUMENT", error_message="Unsupported marketType")

    # Upsert credential
    creds = _load("exchange_credentials.json")
    if not isinstance(creds, list):
        creds = []
    fp = hashlib.sha256(apiKey.encode("utf-8")).hexdigest()
    last4 = apiKey[-4:] if len(apiKey) >= 4 else apiKey
    cred = None
    for c in creds:
        if isinstance(c, dict) and c.get("exchange_id") == ex.get("id") and c.get("api_key_fingerprint") == fp:
            cred = c
            break
    now = _now()
    if cred is None:
        cred = {
            "id": _new_id("cred"),
            "exchange_id": ex.get("id"),
            "api_key_fingerprint": fp,
            "api_key_last4": last4,
            "api_key_encrypted": "opaque:" + base64.b64encode(apiKey.encode("utf-8")).decode("ascii"),
            "secret_encrypted": "opaque:" + base64.b64encode(secret.encode("utf-8")).decode("ascii"),
            "status": "active",
            "last_used_at": now,
            "created_at": now,
            "updated_at": now,
        }
        creds.append(cred)
        _save("exchange_credentials.json", creds)
    else:
        if cred.get("status") != "active":
            return _finalize_and_return(_err("UNAUTHORIZED", "Credential is revoked"), status="error", http_status=401, error_code="AUTH_FAILED", error_message="Credential revoked")
        cred["last_used_at"] = now
        cred["updated_at"] = now
        _save("exchange_credentials.json", creds)

    req_row["credential_id"] = cred.get("id")

    # Offline deterministic "created order" object (no fabrication beyond returning the operation result)
    order_id = _new_id("order")
    ts_ms = int(datetime.datetime.utcnow().timestamp() * 1000)
    result = {
        "id": order_id,
        "clientOrderId": None,
        "timestamp": ts_ms,
        "datetime": _now(),
        "status": "open",
        "symbol": symbol,
        "type": "market",
        "timeInForce": None,
        "side": side,
        "price": None,
        "average": None,
        "amount": amount,
        "filled": 0,
        "remaining": amount,
        "cost": None,
        "trades": [],
        "fee": None,
        "info": {
            "exchange": exchange,
            "marketType": marketType_eff,
            "params": params or {},
            "action": "createOrder",
        },
    }
    summary = {"id": order_id, "status": "open", "symbol": symbol, "side": side, "amount": amount, "type": "market", "marketType": marketType_eff}
    return _finalize_and_return(result, status="success", http_status=200, response_summary=summary)

def set_market_type(marketType, clearCache=None, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0346000" if __import__("os").path.isdir("./environment_mix/0346000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0, tzinfo=datetime.timezone.utc)
    now = now_dt.isoformat().replace("+00:00", "Z")

    allowed = {"spot", "future", "swap", "option", "margin"}

    def _new_id(prefix):
        seed = f"{time.time_ns()}:{os.getpid()}:{prefix}".encode("utf-8")
        return f"{prefix}_{hashlib.sha256(seed).hexdigest()[:26]}"

    def _pick_settings_row(settings_rows):
        if not isinstance(settings_rows, list):
            settings_rows = []
        for r in settings_rows:
            if isinstance(r, dict) and r.get("scope") == "global":
                return r
        for r in settings_rows:
            if isinstance(r, dict):
                return r
        return None

    def _log_request(status_str, market_type=None, cache_action="bypass", error_code=None, error_message=None, response_summary=None, http_status=None):
        reqs = _load("ccxt_requests.json")
        dur = int(max(0, (time.time() - t0) * 1000))
        row = {
            "id": _new_id("ccxt_req"),
            "tool_name": "set-market-type",
            "exchange_id": None,
            "credential_id": None,
            "market_type": market_type,
            "symbol": None,
            "symbols": None,
            "timeframe": None,
            "limit": None,
            "page": None,
            "page_size": None,
            "side": None,
            "amount": None,
            "leverage": None,
            "margin_mode": None,
            "extra_params": {"marketType": marketType, "clearCache": clearCache},
            "cache_action": cache_action,
            "cache_entry_id": None,
            "status": status_str,
            "http_status": http_status,
            "duration_ms": dur,
            "error_code": error_code,
            "error_message": error_message,
            "response_summary": response_summary,
            "created_at": now,
            "updated_at": now,
        }
        reqs.append(row)
        _save("ccxt_requests.json", reqs)
        return row

    if clearCache is None:
        clearCache = True
    if not isinstance(clearCache, bool):
        _log_request("error", error_code="INVALID_ARGUMENT", error_message="clearCache must be boolean", http_status=400)
        return _err("VALIDATION_ERROR", "clearCache must be boolean", error_code="INVALID_ARGUMENT")

    if not isinstance(marketType, str) or marketType not in allowed:
        _log_request("error", error_code="INVALID_ARGUMENT", error_message="marketType must be one of spot,future,swap,option,margin", http_status=400)
        return _err("VALIDATION_ERROR", "marketType must be one of spot,future,swap,option,margin", error_code="INVALID_ARGUMENT")

    settings = _load("server_settings.json")
    row = _pick_settings_row(settings)
    if row is None:
        _log_request("error", error_code="NOT_FOUND", error_message="server settings not found", http_status=404)
        return _err("NOT_FOUND", "server settings not found")

    row["default_market_type"] = marketType
    row["updated_by_tool"] = "set-market-type"
    if not row.get("created_at"):
        row["created_at"] = now
    row["updated_at"] = now
    _save("server_settings.json", settings)

    cache_action = "bypass"
    if clearCache:
        cache = _load("ccxt_cache_entries.json")
        if isinstance(cache, list):
            changed = False
            for e in cache:
                if isinstance(e, dict) and e.get("status") != "invalidated":
                    # lifecycle transition: any -> invalidated is allowed only from valid/stale; schema allows valid->invalidated, stale->invalidated, invalidated->valid
                    if e.get("status") in ("valid", "stale"):
                        e["status"] = "invalidated"
                        e["updated_at"] = now
                        changed = True
            if changed:
                _save("ccxt_cache_entries.json", cache)
        cache_action = "cleared"

    resp = {"marketType": row.get("default_market_type"), "clearCache": clearCache}
    _log_request("success", market_type=marketType, cache_action=cache_action, http_status=200, response_summary=resp)
    return resp
